css:
#page { --shop-walnut:#38271f; --shop-wood:#614332; --shop-brass:#dfbd7f; --shop-paper:#f3ead9; --shop-burgundy:#642e35; }
#page .hero { max-width:1600px; grid-template-columns:minmax(0,.9fr) minmax(0,1.1fr); min-height:660px; background:var(--shop-walnut); padding:40px clamp(24px,4vw,64px) 0; gap:5%; align-items:center; }
#page .hero-copy { margin:0; padding:30px 0 54px; background:transparent; color:var(--shop-paper); }
#page .hero h1 { font-size:clamp(46px,5.8vw,82px); max-width:12ch; }
#page .hero h1 em { color:var(--shop-brass); }
#page .hero-intro { color:var(--shop-paper); max-width:35ch; }
#page .hero-copy>.primary-button { background:var(--shop-brass); color:var(--shop-walnut); min-height:54px; }
#page .bookcase { min-width:0; align-self:end; padding-top:30px; color:var(--shop-paper); }
#page .bookcase-books { display:flex; align-items:end; justify-content:center; gap:18px; padding:18px 12px 0; }
#page .bound-book { position:relative; flex:1; min-width:0; max-width:270px; display:flex; flex-direction:column; align-items:center; gap:16px; text-align:center; padding:30px 20px 22px 28px; min-height:435px; background:#263e33; color:var(--shop-paper); border-radius:5px 12px 3px 3px; box-shadow:inset 7px 0 9px #0005, 9px 12px 16px #1d130e80; border:1px solid #c19a6255; transform:rotate(-3deg); }
#page .bound-book:nth-child(even) { background:var(--shop-burgundy); transform:rotate(2deg); min-height:465px; }
#page .bound-book::before { content:''; position:absolute; inset:12px; border:1px solid #dfbd7f66; border-radius:2px 6px 0 0; pointer-events:none; }
#page .bound-book-author { font-size:11px; line-height:1.5; letter-spacing:.06em; text-transform:uppercase; color:var(--shop-brass); }
#page .bound-book strong { font:500 clamp(24px,2.6vw,37px)/1.12 'Playfair Display',serif; text-wrap:balance; }
#page .bound-book img { width:100%; height:145px; object-fit:cover; margin-top:auto; filter:sepia(.25); }
#page .bound-book-action { display:flex; gap:10px; justify-content:space-between; align-items:center; width:100%; border-top:1px solid #dfbd7f77; padding-top:14px; font-size:12px; }
#page .bound-book:hover strong { text-decoration:underline; text-underline-offset:5px; }
#page .bound-book:focus-visible { outline:3px solid var(--shop-brass); outline-offset:6px; }
#page .bookcase-ledge { position:relative; display:flex; flex-wrap:wrap; gap:12px; justify-content:space-between; padding:20px 24px; margin:8px -16px 0; background:var(--shop-wood); box-shadow:0 14px 20px #1d130e80; border-top:4px solid #8c664a; color:var(--shop-brass); font-size:11px; }
#page .bookcase-ledge>span:first-child { font-family:'Playfair Display',serif; font-size:18px; }
@media(max-width:760px) { #page .hero { grid-template-columns:1fr; gap:0; padding:24px 24px 0; } #page .hero-copy { padding:16px 0 28px; } #page .hero h1 { max-width:14ch; font-size:clamp(43px,10vw,68px); } #page .bookcase { padding-top:0; margin-inline:-8px; } #page .bookcase-books { gap:12px; padding-inline:4px; } #page .bound-book { min-height:350px; padding:26px 14px 20px 20px; gap:12px; } #page .bound-book:nth-child(even) { min-height:380px; } #page .bound-book strong { font-size:clamp(20px,5.4vw,30px); } #page .bound-book img { height:108px; } #page .bound-book-author { font-size:10px; } #page .bookcase-ledge { margin-inline:-8px; padding:16px; } #page .bookcase-ledge>span:last-child { max-width:18ch; text-align:right; } }

#page .site-header { width:100%; max-width:none; padding-inline:max(24px,calc((100vw - 1320px)/2)); min-height:100px; border-bottom:5px double #a38961; background:var(--shop-paper); }
#page .site-header .brand { color:var(--shop-walnut); font-size:clamp(27px,3vw,38px); }
#page .brand-mark { display:none; }
#page .site-nav-desktop>a { background:transparent; color:var(--shop-walnut); border:0; border-bottom:1px solid transparent; padding:14px 12px; }
#page .site-nav-desktop>a:hover,#page .site-nav-desktop>a[aria-current=page] { color:#642e35; border-color:#642e35; background:transparent; }
#page .site-nav-desktop { gap:12px; }
@media(max-width:760px) { #page .site-header { min-height:120px; padding-inline:20px; } #page .site-header .site-nav-quick { border-top-color:#b5a58d; } #page .site-nav-mobile nav { background:var(--shop-paper); } }
#page .site-header .site-nav-desktop>a:first-child { background:transparent; color:var(--shop-walnut); border-bottom:1px solid #a38961; }

#page .hero-how { background:var(--shop-paper); color:var(--shop-walnut); padding:18px 22px; grid-template-columns:1fr 1fr; gap:12px 24px; margin-top:26px; border-radius:0 0 14px 0; max-width:460px; }
#page .hero-how div { display:grid; grid-template-columns:24px 1fr; align-items:center; border-bottom:1px solid #c7b89f; border-top:0; padding:0 0 12px; }
#page .hero-how div span { font:600 12px 'DM Sans',sans-serif; color:#642e35; }
#page .hero-how strong { font:500 18px/1.25 'Playfair Display',serif; }
#page .hero-how>a { min-height:44px; padding:4px 0; border:0; color:#51392b; }
@media(max-width:420px) { #page .hero-how { padding:16px; column-gap:12px; } #page .hero-how div { grid-template-columns:1fr; gap:6px; } }

#page .home-cast { align-items:start; padding-block:90px; grid-template-columns:minmax(0,.8fr) minmax(0,1.2fr); }
#page .home-cast-stories { background:var(--shop-wood); padding:24px; box-shadow:inset 0 8px 15px #20140e55; }
#page .home-cast-story,#page .home-cast-story:nth-child(even) { background:var(--shop-paper); padding:20px; margin:0; }
#page .home-cast-story+.home-cast-story { margin-top:18px; }
#page .home-cast-book { border-top:0; border-bottom-color:#bba78a; }
#page .home-cast-story a { grid-template-columns:48px minmax(0,1fr) auto; gap:16px; padding:20px 0; }
#page .home-cast-initial,#page .home-cast-story:nth-child(even) .home-cast-initial { width:48px; height:60px; border:1px solid #aa8a64; background:transparent; color:var(--shop-burgundy); font-size:34px; }
#page .home-cast-person strong { font-size:clamp(22px,2.6vw,32px); }
@media(max-width:760px) { #page .home-cast { grid-template-columns:1fr; } #page .home-cast-stories { padding:14px; } #page .home-cast-story { padding:16px; } }

#page .first-scene { width:min(1320px,calc(100% - 48px)); background:var(--shop-walnut); padding:clamp(20px,4vw,54px); gap:0; align-items:stretch; }
#page .first-scene>div:first-child { padding:clamp(24px,4vw,52px); background:var(--shop-paper); color:var(--shop-walnut); }
#page .first-scene h2 { font-size:clamp(40px,5vw,64px); }
#page .first-scene h2 em { color:var(--shop-burgundy); }
#page .first-scene>div:first-child>p { color:#51392b; }
#page .first-scene>div:first-child>a { background:var(--shop-burgundy); color:var(--shop-paper); }
#page .first-scene-art { min-height:520px; }
#page .first-scene-thread { background:var(--shop-walnut); padding:16px; inset:auto 20px 20px; border:0; }
@media(max-width:760px) { #page .first-scene { width:calc(100% - 32px); padding:16px; } #page .first-scene-art { min-height:340px; } }

#page .reading-index-list { border:0; background:var(--shop-wood); padding:20px; display:grid; gap:14px; }
#page .reading-index-list>a { background:var(--shop-paper); border:0; grid-template-columns:34px minmax(0,1fr) auto; padding:28px 24px; border-radius:0 0 16px 0; }
#page .reading-index-number { font-size:22px; color:var(--shop-burgundy); }
#page .reading-index-list strong { font-size:clamp(25px,3vw,38px); }
#page .reading-index-list small { color:#642e35; }
#page .reading-index-list>a:hover { background:#fff7e8; }
@media(max-width:760px) { #page .reading-index-list { padding:14px; } #page .reading-index-list>a { padding:22px 16px; grid-template-columns:24px minmax(0,1fr) auto; gap:12px; } }

#page .next-step { background:var(--shop-paper); color:var(--shop-walnut); }
#page .next-step-heading h2 em { color:var(--shop-burgundy); }
#page .next-step-heading>p:last-child { color:#51392b; }
#page .next-step-options { display:grid; grid-template-columns:1fr 1fr; gap:22px; border:0; padding-bottom:16px; border-bottom:8px solid var(--shop-wood); }
#page .next-step-options a { padding:30px 24px; min-height:340px; background:var(--shop-burgundy); color:var(--shop-paper); justify-content:end; border:1px solid #a98659; box-shadow:inset 9px 0 12px #20140e66; }
#page .next-step-options a:nth-child(even) { background:#263e33; }
#page .next-step-options a::after { display:none; }
#page .next-step-options strong { font-size:clamp(26px,3vw,38px); }
#page .next-step-options a>span:not(.next-step-number) { color:var(--shop-paper); }
#page .next-step-options .next-step-number { color:var(--shop-brass); }
#page .next-step-options b { margin-top:24px; }
@media(max-width:760px) { #page .next-step-options { gap:14px; } #page .next-step-options a { padding:26px 18px; min-height:330px; } }
@media(max-width:380px) { #page .next-step-options { grid-template-columns:1fr; } }
#page .next-step-inner { grid-template-columns:minmax(0,.85fr) minmax(0,1.15fr); gap:6%; }
#page .next-step-options a:first-child { background:var(--shop-burgundy); }
#page .next-step-options a:is(:first-child,:last-child)>span:not(.next-step-number) { color:var(--shop-paper); }
#page .next-step-options a:is(:first-child,:last-child) .next-step-number { color:var(--shop-brass); }
@media(max-width:760px) { #page .next-step-inner { grid-template-columns:1fr; gap:30px; } }

#page .resume-shelf:not([hidden]) { background:var(--shop-walnut); padding:32px; color:var(--shop-paper); }
#page .resume-heading { border-bottom:1px solid #a18b6f; padding-bottom:22px; }
#page .resume-heading>p { color:var(--shop-paper); }
#page .resume-item { background:var(--shop-paper); color:var(--shop-walnut); padding:24px; border-bottom:1px dashed #9d8468; }
#page .resume-list { gap:12px; }
#page .resume-action { color:var(--shop-burgundy); }
#page .resume-item>span:first-child { display:none; }
@media(max-width:760px) { #page .resume-shelf:not([hidden]) { padding:24px; } #page .resume-item { padding:20px; } }

#page .site-footer { background:var(--shop-walnut); border-top:10px solid var(--shop-wood); color:var(--shop-paper); }
#page .site-footer-inner { padding-top:60px; grid-template-columns:1.2fr 1fr; }
#page .site-footer-intro .brand { font-size:clamp(36px,5vw,72px); }
#page .site-footer nav { border-left:1px solid #8e7457; padding-left:40px; }
#page .site-footer nav a { border-bottom:1px solid #8e7457; width:100%; min-height:44px; display:flex; align-items:center; }
#page .site-footer nav p { color:var(--shop-brass); }
#page .site-footer-bottom { border-color:#8e7457; }
@media(max-width:760px) { #page .site-footer-inner { grid-template-columns:1fr; } #page .site-footer nav { border-left:0; padding-left:0; } }

#page .collection-heading { display:grid; grid-template-columns:1.2fr 1fr; gap:6%; background:var(--shop-walnut); color:var(--shop-paper); padding:clamp(28px,5vw,64px); margin-bottom:40px; border:5px double #a48a61; text-align:left; }
#page .collection-heading h1 { font-size:clamp(42px,5vw,68px); }
#page .collection-heading h1 em { color:var(--shop-brass); }
#page .collection-intro { align-self:end; }
#page .collection-intro p { color:var(--shop-paper); font-size:16px; line-height:1.7; }
#page .collection-intro>span { display:none; }
@media(max-width:760px) { #page .collection-heading { grid-template-columns:1fr; gap:20px; padding:28px; } }

#page .library-finder:not([hidden]) { display:grid; grid-template-columns:minmax(0,.7fr) minmax(0,1.3fr); background:var(--shop-wood); padding:24px; gap:24px; box-shadow:inset 0 5px 9px #21140e66; }
#page .library-finder label { border:1px solid #b99561; padding:16px 20px; text-align:center; color:var(--shop-paper); font-family:'Playfair Display',serif; font-size:20px; }
#page .library-finder-controls { width:100%; background:var(--shop-paper); padding:10px 16px; }
#page .library-finder-controls>div { border-color:#a38961; }
#page .library-finder button { background:var(--shop-burgundy); min-height:44px; }
@media(max-width:760px) { #page .library-finder:not([hidden]) { grid-template-columns:1fr; gap:16px; padding:20px; } }

#page .collection-list { grid-template-columns:repeat(2,minmax(0,1fr)); background:var(--shop-walnut); padding:36px 32px 0; gap:32px; border-bottom:14px solid var(--shop-wood); box-shadow:0 14px 20px #38271f22; }
#page .collection-item,#page .collection-list li:nth-child(even) .collection-item { background:#263e33; color:var(--shop-paper); display:flex; flex-direction:column; padding:36px 28px 28px; border-radius:5px 14px 0 0; border:1px solid #b9956177; box-shadow:inset 12px 0 16px #0e1c1666; min-height:540px; }
#page .collection-list li:nth-child(even) .collection-item { background:var(--shop-burgundy); }
#page .collection-visual { position:static; width:100%; height:180px; min-height:0; margin:12px 0 24px; overflow:hidden; }
#page .collection-visual img { width:100%; height:100%; object-fit:cover; }
#page .collection-number { position:static; writing-mode:horizontal-tb; transform:none; color:var(--shop-brass); }
#page .collection-book { margin:0 0 24px; padding:0; }
#page .collection-item .collection-book>span,#page .collection-book .collection-description { color:var(--shop-paper); }
#page .collection-book strong { font-size:clamp(32px,4vw,52px); }
#page .collection-item .collection-link,#page .collection-item .collection-link span { color:var(--shop-paper); }
#page .collection-link { margin-top:auto; border-color:#ba9c73; }
#page .collection-item:hover { background:#304e40; }
#page .collection-list li:nth-child(even) .collection-item:hover { background:#783d45; }
@media(max-width:760px) { #page .collection-list { padding:24px 20px 0; gap:20px; grid-template-columns:1fr; } #page .collection-item { min-height:480px; padding:28px; } #page .collection-visual { height:180px; } }

#page .shelf-note { position:relative; width:min(740px,100%); margin:70px auto; background:var(--shop-paper); color:var(--shop-walnut); padding:36px 42px; display:block; border-block:1px solid #9d8468; transform:rotate(-1deg); }
#page .shelf-note>span { display:none; }
#page .shelf-note h2 { font-size:clamp(28px,4vw,42px); max-width:22ch; }
#page .shelf-note a { display:inline-flex; min-height:48px; align-items:center; color:var(--shop-burgundy); }
@media(max-width:760px) { #page .shelf-note { padding:28px; transform:none; } }

#page .library-people { display:grid; grid-template-columns:1.2fr 1fr; align-items:center; gap:40px; background:var(--shop-walnut); color:var(--shop-paper); padding:44px; border-bottom:8px solid var(--shop-wood); }
#page .library-people>div { border-left:1px solid #b99561; padding-left:28px; }
#page .library-people h2 { font-size:clamp(34px,4vw,52px); }
#page .library-people p:not(.eyebrow) { color:var(--shop-paper); }
#page .library-people .eyebrow { display:none; }
#page .library-people .primary-button { justify-self:center; background:var(--shop-paper); color:var(--shop-walnut); }
@media(max-width:760px) { #page .library-people { grid-template-columns:1fr; padding:28px; gap:24px; } #page .library-people .primary-button { justify-self:start; } }

#page .library-authors { display:grid; grid-template-columns:1fr 1fr; gap:6%; align-items:center; }
#page .library-authors ul { padding:16px; background:var(--shop-walnut); display:grid; gap:14px; }
#page .library-authors li { list-style:none; background:var(--shop-wood); }
#page .library-authors li a { padding:24px; min-height:110px; border:0; display:flex; justify-content:space-between; align-items:center; color:var(--shop-paper); }
#page .library-authors li a>span:first-child { display:none; }
#page .library-authors strong { border:1px solid #c4a16a; padding:12px 20px; font:500 clamp(22px,2.6vw,32px)/1.2 'Playfair Display',serif; }
@media(max-width:760px) { #page .library-authors { grid-template-columns:1fr; gap:26px; } #page .library-authors li a { padding:20px; } }

#page .directory-heading { background:var(--shop-paper); color:var(--shop-walnut); display:grid; grid-template-columns:1.2fr 1fr; gap:8%; padding:40px; border:1px solid #b9a382; margin-bottom:40px; box-shadow:0 10px 22px #38271f12; }
#page .directory-heading h1 { font-size:clamp(42px,5vw,68px); }
#page .directory-heading h1 em { color:var(--shop-burgundy); }
#page .directory-heading>div:last-child { align-self:end; border-top:1px solid #b9a382; padding-top:24px; }
@media(max-width:760px) { #page .directory-heading { padding:26px; grid-template-columns:1fr; gap:24px; } }

#page .story-index { display:grid; grid-template-columns:.65fr 1.35fr; gap:30px; padding:28px; background:var(--shop-walnut); color:var(--shop-paper); }
#page .story-index-intro p { color:var(--shop-paper); }
#page .story-index-links { display:grid; grid-template-columns:1fr 1fr; gap:16px; }
#page .story-index-links a { display:flex; flex-direction:column; align-items:start; gap:20px; min-height:190px; padding:26px; border:1px solid #a5885f; background:var(--shop-wood); color:var(--shop-paper); }
#page .story-index-number { color:var(--shop-brass); }
#page .story-index-links small { color:var(--shop-paper); }
#page .story-index-links strong { font-size:25px; }
#page .story-index-arrow { align-self:end; }
@media(max-width:760px) { #page .story-index { grid-template-columns:1fr; padding:20px; } #page .story-index-links { grid-template-columns:1fr; } #page .story-index-links a { min-height:150px; } }

#page .directory-people { display:grid; grid-template-columns:1fr 1fr; gap:20px; background:var(--shop-paper); padding:24px; border-block:1px solid #b9a382; }
#page .directory-people li { border:0; padding:0; }
#page .directory-people a { height:100%; background:#fffaf0; grid-template-columns:52px minmax(0,1fr) auto; padding:26px 20px; gap:16px; border-top:1px solid #b9a382; }
#page .directory-initial { width:52px; height:66px; background:transparent; border:1px solid #b9a382; color:var(--shop-burgundy); font-size:36px; }
#page .directory-person strong { font-size:clamp(24px,3vw,36px); }
@media(max-width:900px) { #page .directory-people { grid-template-columns:1fr; padding:18px; } }

#page .directory-next { display:grid; grid-template-columns:1.3fr 1fr; gap:40px; padding:48px; background:var(--shop-paper); color:var(--shop-walnut); border:5px double #a38961; }
#page .directory-next h2 { font-size:clamp(34px,4.5vw,56px); }
#page .directory-next p { color:#51392b; }
#page .directory-next .eyebrow { display:none; }
#page .directory-next .primary-button { align-self:center; justify-self:center; border:1px solid var(--shop-burgundy); background:transparent; color:var(--shop-burgundy); padding:24px; }
@media(max-width:760px) { #page .directory-next { grid-template-columns:1fr; padding:28px; gap:24px; } #page .directory-next .primary-button { justify-self:start; } }

#page .book-opening { grid-template-columns:1.15fr .85fr; gap:0; background:var(--shop-walnut); padding:24px; border-radius:6px 16px 6px 6px; }
#page .book-opening-copy { background:var(--shop-paper); color:var(--shop-walnut); padding:clamp(28px,4vw,60px); border-radius:2px 0 0 2px; box-shadow:inset -10px 0 18px #6c513322; }
#page .book-opening h1 { font-size:clamp(42px,5vw,68px); }
#page .book-opening-art { min-height:590px; border:1px solid #ac8e61; }
#page .book-opening-actions { border-top:1px solid #b7a17e; padding-top:24px; }
@media(max-width:760px) { #page .book-opening { grid-template-columns:1fr; padding:14px; } #page .book-opening-copy { padding:28px; } #page .book-opening-art { min-height:380px; } }

#page .reading-entry { background:var(--shop-paper); padding:40px; border:1px solid #b7a17e; grid-template-columns:.8fr 1.2fr; gap:40px; }
#page .reading-entry-action { background:#fffaf0; padding:26px; border-top:4px double #b7a17e; }
#page .reading-entry-symbol { display:none; }
#page .reading-entry-choices>div { gap:0; display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); }
#page .reading-entry-choice { border-radius:0; border:1px solid #b7a17e; padding:16px; background:transparent; }
#page .reading-entry-choice:has(input:checked) { background:var(--shop-burgundy); color:var(--shop-paper); }
#page .reading-entry-choice:has(input:checked) small { color:var(--shop-paper); }
#page .reading-entry-submit { width:100%; margin-top:20px; background:var(--shop-burgundy); color:var(--shop-paper); min-height:56px; }
@media(max-width:760px) { #page .reading-entry { grid-template-columns:1fr; padding:24px; gap:24px; } #page .reading-entry-action { padding:20px; } }

#page .book-cast-preview { background:var(--shop-walnut); padding:40px; color:var(--shop-paper); }
#page .book-cast-preview-head>p { color:var(--shop-paper); }
#page .book-cast-preview-list { display:grid; grid-template-columns:1fr 1fr; gap:20px; }
#page .book-cast-preview-list>a { background:var(--shop-paper); color:var(--shop-walnut); padding:26px; border-radius:0 0 16px 0; border:0; grid-template-columns:48px minmax(0,1fr) auto; }
#page .book-cast-preview-initial { width:48px; height:64px; background:transparent; color:var(--shop-burgundy); border:1px solid #b7a17e; }
#page .book-cast-preview-all { color:var(--shop-paper); min-height:44px; display:inline-flex; align-items:center; }
@media(max-width:900px) { #page .book-cast-preview-list { grid-template-columns:1fr; } }
@media(max-width:760px) { #page .book-cast-preview { padding:24px; } }

#page .chapter-shelf { background:transparent; padding:0; grid-template-columns:.7fr 1.3fr; gap:40px; }
